const EntityDefinition* find_entity_definition(std::uint8_t type_id) noexcept {
    // Ids are dense 0..39, asserted by the generator, so this indexes directly.
    if (type_id >= std::size(definitions)) {
        return nullptr;
    }
    return &definitions[type_id];
}

std::span<const EntityDefinition> entity_catalog() noexcept {
    return definitions;
}

